<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch,nextTick} from 'vue'
import {deploymentBase,subscriptionLink,normalizeToken,normalizeRestoredToken} from './addresses'
import {copyText} from './clipboard'
import {useRoute,useRouter} from 'vue-router'
import {RequestScope,StaleNavigation,runRequest} from './navigation'
const responses=new RequestScope()
const route=useRoute(),router=useRouter()
const returnTo=ref('/subscriptions')
let navigation=0
type Kind='proxy'|'server'|'credential'|'policy'
type Data=Record<string,string|number>
interface Entity{id:string;kind:Kind;label:string;data:Data;hasPassword?:boolean}
interface Subscription{id:string;label:string;proxyId:string;credentialId:string;policyId:string;enabled:boolean;revision:number;refreshIntervalSeconds:number;minClientVersionCode:number;hasSavedToken?:boolean}
interface Preview{configuration:unknown;expectedRevision:number;draftDigest:string}
interface Version{revision:number;createdAt:number;note:string}
interface Feedback{deviceId:string;platform:string;versionCode:number;revision:number;status:string;errorCode:string;seenAt:number}
const labels:Record<Kind,string>={proxy:'HTTP 代理',server:'Jellyfin 服务',credential:'个人授权',policy:'播放策略'}
const kinds:Kind[]=['proxy','server','credential','policy']
const apiRoot=new URL('api/v1/',deploymentBase(window.location.href)).href
const base=apiRoot+'admin'
const starting=ref(true),bootFailed=ref(false),setupRequired=ref(false)
const setup=reactive({code:'',username:'admin',password:'',confirmation:''})
const csrf=ref(''),username=ref(''),authenticated=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const login=reactive({username:'',password:''}),tab=ref<Kind|'subscriptions'>('subscriptions')
const entities=reactive<Record<Kind,Entity[]>>({proxy:[],server:[],credential:[],policy:[]}),subscriptions=ref<Subscription[]>([])
const entityDraft=ref<{id:string;label:string;data:Data;hasPassword:boolean}|null>(null)
const subscriptionDraft=ref<Subscription|null>(null),selected=ref<Subscription|null>(null),preview=ref<Preview|null>(null),versions=ref<Version[]>([]),feedback=ref<Feedback[]>([]),link=ref('')
const subscriptionToken=ref(''),tokenValue=ref(''),tokenDialog=ref(false)
const restoreLinkDialog=ref(false),originalLink=ref('')
const passwordDialog=ref(false),password=reactive({oldPassword:'',newPassword:''})
const resolutions=['auto','screen','360p','480p','720p','1080p','4k','8k']
const resolutionNames:Record<string,string>={auto:'自动',screen:'屏幕分辨率','360p':'360p','480p':'480p','720p':'720p','1080p':'1080p','4k':'4K','8k':'8K'}
const rates=[0,120000000,80000000,60000000,40000000,20000000,15000000,10000000,8000000,6000000,4000000,3000000,1500000,720000,420000]
const rateLabel=(value:number)=>value===0?'自动':value>=1000000?`${value/1000000} Mbps`:`${value/1000} kbps`
const live=computed(()=>subscriptions.value.filter(v=>v.enabled&&v.revision>0).length)
async function api<T>(path:string,method='GET',body?:unknown):Promise<T>{
 const {response,result}=await runRequest(path,responses,async()=>{const response=await fetch(base+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json',...(method==='GET'?{}:{'X-CSRF-Token':csrf.value})},body:body===undefined?undefined:JSON.stringify(body)});return {response,result:await response.json()}})
 if(!response.ok){if(response.status===401){authenticated.value=false;csrf.value=''}throw new Error(result.message||'操作失败，请重试')};return result as T
}
async function action(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await work()}catch(e){if(!(e instanceof StaleNavigation))error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function reload(){const result=await Promise.all([api<Subscription[]>('/subscriptions'),...kinds.map(k=>api<Entity[]>('/entities/'+k))]);subscriptions.value=result[0] as Subscription[];kinds.forEach((k,i)=>entities[k]=result[i+1] as Entity[]);if(selected.value)selected.value=subscriptions.value.find(s=>s.id===selected.value?.id)||null}
async function signIn(){await action(async()=>{starting.value=true;try{const session=await api<{username:string;csrf:string}>('/login','POST',login);csrf.value=session.csrf;username.value=session.username;login.password='';await reload();authenticated.value=true}finally{starting.value=false;await syncRoute()}})}
function switchTab(value:Kind|'subscriptions'){void router.push({name:value})}
function closeSubscription(){void router.push({name:'subscriptions'})}
function clearTransient(){entityDraft.value=null;subscriptionDraft.value=null;subscriptionToken.value='';tokenDialog.value=false;tokenValue.value='';restoreLinkDialog.value=false;originalLink.value='';passwordDialog.value=false;password.oldPassword='';password.newPassword='';link.value=''}
async function syncRoute(){
 const turn=++navigation
 if(starting.value||bootFailed.value)return
 responses.invalidate()
 clearTransient()
 if(setupRequired.value){if(route.name!=='setup')await router.replace({name:'setup'});return}
 if(!authenticated.value){if(route.meta.tab)returnTo.value=route.fullPath;if(route.name!=='login')await router.replace({name:'login'});return}
 if(route.name==='login'||route.name==='setup'){await router.replace(returnTo.value);return}
 const target=route.meta.tab
 if(target!=='subscriptions'&&!kinds.includes(target as Kind)){await router.replace({name:'subscriptions'});return}
 tab.value=target as Kind|'subscriptions';selected.value=null;preview.value=null;versions.value=[];feedback.value=[];error.value='';notice.value=''
 if(route.name!=='subscription-detail')return
 const id=String(route.params.id),entry=subscriptions.value.find(s=>s.id===id)
 if(!entry){await router.replace({name:'subscriptions'});notice.value='订阅不存在或已删除';return}
 selected.value=entry
 try{const [history,reports]=await Promise.all([api<Version[]>('/subscriptions/'+id+'/versions'),api<Feedback[]>('/subscriptions/'+id+'/feedback')]);if(turn!==navigation||!authenticated.value)return;versions.value=history;feedback.value=reports}
 catch(e){if(turn===navigation)error.value=e instanceof Error?e.message:'详情读取失败'}
}
watch([()=>route.fullPath,authenticated,setupRequired],()=>{void syncRoute()})
function editEntity(entity?:Entity){if(tab.value==='subscriptions')return;const defaults:Record<Kind,Data>={proxy:{type:'http',host:'',port:8080,username:'',password:''},server:{baseUrl:''},credential:{serverId:entities.server[0]?.id||'',username:'',password:''},policy:{resolution:'1080p',totalBitrateBps:4000000}};entityDraft.value={id:entity?.id||'',label:entity?.label||'',data:entity?{...entity.data,password:''}:{...defaults[tab.value]},hasPassword:!!entity?.hasPassword};if(tab.value==='server'||tab.value==='policy')delete entityDraft.value.data.password}
async function saveEntity(){await action(async()=>{const d=entityDraft.value;if(!d||tab.value==='subscriptions')return;const data={...d.data};if(d.id&&d.hasPassword&&data.password==='')delete data.password;await api('/entities/'+tab.value+(d.id?'/'+d.id:''),d.id?'PUT':'POST',{label:d.label,data});entityDraft.value=null;await reload();notice.value='草稿已保存。已发布的订阅不会改变，请到订阅详情预览并发布。'})}
function related(entity:Entity){if(entity.kind==='server'){const ids=entities.credential.filter(c=>c.data.serverId===entity.id).map(c=>c.id);return subscriptions.value.filter(s=>ids.includes(s.credentialId)).length};return subscriptions.value.filter(s=>entity.kind==='proxy'?s.proxyId===entity.id:entity.kind==='credential'?s.credentialId===entity.id:s.policyId===entity.id).length}
async function deleteEntity(entity:Entity){if(!confirm('确认删除这条配置？被引用的配置不能删除。'))return;await action(async()=>{await api('/entities/'+entity.kind+'/'+entity.id,'DELETE');await reload()})}
function editSubscription(value?:Subscription){subscriptionToken.value='';subscriptionDraft.value=value?{...value}:{id:'',label:'',proxyId:'',credentialId:entities.credential[0]?.id||'',policyId:entities.policy[0]?.id||'',enabled:true,revision:0,refreshIntervalSeconds:900,minClientVersionCode:57}}
async function saveSubscription(){await action(async()=>{const d=subscriptionDraft.value;if(!d)return;const result=await api<{subscription:Subscription;link:string}>('/subscriptions'+(d.id?'/'+d.id:''),d.id?'PUT':'POST',{...d,...(d.id?{}:{token:normalizeToken(subscriptionToken.value)})});subscriptionDraft.value=null;subscriptionToken.value='';await reload();await router.push({name:'subscription-detail',params:{id:result.subscription.id}});await nextTick();link.value=result.link?subscriptionLink(result.link,window.location.href):'';preview.value=null;notice.value='订阅草稿已保存。请预览并发布后再在手机使用。'})}
function inspect(value:Subscription){void router.push({name:'subscription-detail',params:{id:value.id}})}
async function getPreview(){await action(async()=>{if(selected.value)preview.value=await api<Preview>('/subscriptions/'+selected.value.id+'/preview')})}
async function publish(){if(!confirm('确认发布当前预览？关联手机将在下次检查时获取新配置。'))return;await action(async()=>{if(!selected.value||!preview.value)return;await api('/subscriptions/'+selected.value.id+'/publish','POST',{expectedRevision:preview.value.expectedRevision,draftDigest:preview.value.draftDigest,note:'管理后台发布'});preview.value=null;await reload();versions.value=await api<Version[]>('/subscriptions/'+selected.value.id+'/versions');notice.value='新版本已发布。'})}
async function rollback(version:number){if(!confirm('确认以该历史内容创建一个新版本？'))return;await action(async()=>{if(!selected.value)return;await api('/subscriptions/'+selected.value.id+'/rollback','POST',{revision:version,expectedRevision:selected.value.revision});await reload();preview.value=null;versions.value=await api<Version[]>('/subscriptions/'+selected.value.id+'/versions');notice.value='已创建回滚版本。'})}
async function toggle(){if(!selected.value||!confirm(selected.value.enabled?'确认停用订阅？此操作不会撤销已经取得的 Jellyfin 凭据。':'确认重新启用订阅？'))return;await action(async()=>{if(!selected.value)return;await api('/subscriptions/'+selected.value.id+'/state','POST',{enabled:!selected.value.enabled});await reload()})}
function rotate(){if(!selected.value)return;tokenValue.value='';error.value='';tokenDialog.value=true}
async function updateToken(random=false){await action(async()=>{if(!selected.value)return;const token=random?'':normalizeToken(tokenValue.value);if(!random&&!token)throw new Error('请输入要设置或恢复的令牌');if(!confirm('确认设置令牌？原链接会立即失效；恢复原令牌时链接保持不变。'))return;const result=await api<{link:string}>('/subscriptions/'+selected.value.id+'/token','POST',{token});tokenValue.value='';tokenDialog.value=false;await reload();link.value=subscriptionLink(result.link,window.location.href)})}
async function removeSubscription(){if(!selected.value||!confirm('确认删除订阅及发布历史？此操作无法撤销。'))return;await action(async()=>{if(!selected.value)return;await api('/subscriptions/'+selected.value.id,'DELETE');selected.value=null;await reload();await router.replace({name:'subscriptions'})})}
function copiedNotice(value:string){return value.startsWith('http:')?'订阅链接已复制。当前为 HTTP 地址，Android 订阅要求 HTTPS，请从手机可达的 HTTPS 后台地址复制。':'订阅链接已复制。'}
async function copyLink(){notice.value=await copyText(link.value)?copiedNotice(link.value):'浏览器未允许复制，请选中链接后手动复制。'}
async function copyReturnedLink(path:string){const full=subscriptionLink(path,window.location.href);if(await copyText(full))notice.value=copiedNotice(full);else{link.value=full;notice.value='浏览器未允许自动复制，请在弹窗点击复制或手动复制。'}}
async function copySavedLink(){if(!selected.value)return;if(!selected.value.hasSavedToken){originalLink.value='';error.value='';restoreLinkDialog.value=true;return}await action(async()=>{if(!selected.value)return;const result=await api<{link:string}>('/subscriptions/'+selected.value.id+'/link','POST');await copyReturnedLink(result.link)})}
async function restoreOriginalLink(){await action(async()=>{if(!selected.value)return;const result=await api<{link:string}>('/subscriptions/'+selected.value.id+'/link/restore','POST',{token:normalizeRestoredToken(originalLink.value)});originalLink.value='';restoreLinkDialog.value=false;await reload();await copyReturnedLink(result.link)})}
async function changePassword(){await action(async()=>{await api('/password','POST',password);password.oldPassword='';password.newPassword='';passwordDialog.value=false;authenticated.value=false;csrf.value='';notice.value='管理员密码已更新，请重新登录。'})}
const time=(value:number)=>new Date(value*1000).toLocaleString()
const name=(kind:Kind,id:string)=>entities[kind].find(e=>e.id===id)?.label||'未找到配置'
async function setupRequest<T>(path:string,method='GET',body?:unknown):Promise<T>{
 const response=await fetch(apiRoot+'setup/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)})
 const result=await response.json();if(!response.ok)throw new Error(result.message||'初始化失败，请重试');return result as T
}
async function boot(){starting.value=true;bootFailed.value=false;error.value='';try{
 setupRequired.value=(await setupRequest<{required:boolean}>('status')).required
 if(!setupRequired.value){try{const session=await api<{username:string;csrf:string}>('/session');csrf.value=session.csrf;username.value=session.username;authenticated.value=true;await reload()}catch{/* Missing session opens login. */}}
}catch{bootFailed.value=true;error.value='无法连接服务，请稍后重试'}finally{starting.value=false;await syncRoute()}}
async function completeSetup(){await action(async()=>{
 if(setup.password!==setup.confirmation)throw new Error('两次密码输入不一致')
 await setupRequest('complete','POST',{code:setup.code,username:setup.username,password:setup.password})
 login.username='';setup.code='';setup.password='';setup.confirmation='';setupRequired.value=false;notice.value='初始化完成，请使用刚创建的账号登录。'
})}
onMounted(boot)
</script>

<template>
 <div class="shell">
  <header><div class="brand"><span class="mark">Z</span><div>z-jellyfin-hub<small>家庭影音配置中心</small></div></div><div v-if="authenticated" class="tools"><span>{{username}}</span><button @click="passwordDialog=true">修改密码</button><button @click="action(async()=>{await api('/logout','POST',{});authenticated=false;csrf=''})">退出</button></div></header>
  <main v-if="starting||bootFailed" class="login"><h1>{{starting?'正在连接':'连接失败'}}</h1><p v-if="bootFailed" class="error" role="alert">{{error}}</p><button v-if="bootFailed" @click="boot">重新连接</button></main>
  <main v-else-if="setupRequired" class="login"><p class="eyebrow">首次使用</p><h1>创建管理账号</h1><p class="muted">在部署主机执行 <code>docker compose exec hub hub setup-code</code> 获取一次性初始化码。</p><form @submit.prevent="completeSetup"><label>初始化码<input v-model="setup.code" type="password" required autocomplete="off" maxlength="43"></label><label>管理员账号<input v-model="setup.username" required autocomplete="username" maxlength="120"></label><label>管理员密码<input v-model="setup.password" type="password" required minlength="8" maxlength="1024" autocomplete="new-password"></label><label>确认密码<input v-model="setup.confirmation" type="password" required minlength="8" maxlength="1024" autocomplete="new-password"></label><p v-if="error" role="alert" class="error">{{error}}</p><button class="primary" :disabled="busy">{{busy?'正在初始化…':'完成初始化'}}</button><button type="button" :disabled="busy" @click="boot">重新检查</button></form></main>
  <main v-else-if="!authenticated" class="login"><p class="eyebrow">管理员入口</p><h1>集中配置，轻松连接</h1><p class="muted">管理个人订阅、Jellyfin 授权和播放策略。</p><form @submit.prevent="signIn"><label>账号<input v-model="login.username" autocomplete="username" required maxlength="256"></label><label>密码<input v-model="login.password" type="password" autocomplete="current-password" required maxlength="1024"></label><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><button class="primary" :disabled="busy">{{busy?'正在登录…':'登录管理后台'}}</button></form></main>
  <div v-else class="workspace"><aside aria-label="配置分类"><button :class="{active:tab==='subscriptions'}" @click="switchTab('subscriptions')">个人订阅</button><button v-for="kind in kinds" :key="kind" :class="{active:tab===kind}" @click="switchTab(kind)">{{labels[kind]}}</button><p>草稿保存后需显式发布。<br>字幕、音轨继续由手机控制。</p></aside>
   <main class="content"><div class="page-heading"><div><p class="eyebrow">配置管理</p><h1>{{tab==='subscriptions'?'个人订阅':labels[tab]}}</h1></div><button :disabled="busy" @click="action(reload)">刷新</button></div>
    <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>
    <div v-if="tab==='subscriptions'"><div class="stats"><div><strong>{{subscriptions.length}}</strong><span>个人订阅</span></div><div><strong>{{live}}</strong><span>已发布且启用</span></div><div><strong>{{entities.credential.length}}</strong><span>个人授权</span></div></div><div class="section-heading"><h2>订阅列表</h2><button class="primary" :disabled="busy" @click="editSubscription()">新建订阅</button></div><p class="muted">每人独立链接，同一人的多台设备可复用，可在订阅详情复制链接。</p><div class="table-wrap subscription-list"><table aria-label="个人订阅列表"><thead><tr><th scope="col">使用者</th><th scope="col">授权 / 策略</th><th scope="col">已发布版本</th><th scope="col">状态</th><th scope="col" aria-label="操作"></th></tr></thead><tbody><tr v-for="sub in subscriptions" :key="sub.id"><td data-label="使用者">{{sub.label}}</td><td data-label="授权 / 策略">{{name('credential',sub.credentialId)}}<small>{{name('policy',sub.policyId)}}</small></td><td data-label="已发布版本">{{sub.revision?'v'+sub.revision:'尚未发布'}}</td><td data-label="状态"><span class="badge" :class="{off:!sub.enabled}">{{sub.enabled?'启用':'停用'}}</span></td><td data-label="操作"><button :disabled="busy" @click="inspect(sub)">详情</button></td></tr><tr v-if="!subscriptions.length"><td colspan="5" class="empty">先建立代理、服务、个人授权和播放策略，再创建订阅。</td></tr></tbody></table></div>
     <section v-if="selected" class="detail"><div class="section-heading"><div><p class="eyebrow">订阅详情</p><h2>{{selected.label}}</h2></div><button @click="closeSubscription">关闭</button></div><div class="actions"><button :disabled="busy" @click="editSubscription(selected)">编辑草稿</button><button class="primary" :disabled="busy" @click="getPreview">预览发布</button><button :disabled="busy" @click="toggle">{{selected.enabled?'停用':'启用'}}</button><button :disabled="busy" @click="copySavedLink">复制订阅链接</button><button :disabled="busy" @click="rotate">设置／恢复令牌</button><button class="danger" :disabled="busy" @click="removeSubscription">删除</button></div><p class="muted">发布版本与草稿分开管理。修改模板不会直接更改手机配置。</p><p v-if="!selected.hasSavedToken" class="muted">该旧订阅尚未保存原令牌。点击复制订阅链接后补录一次，设备现有链接保持有效。</p><div v-if="preview" class="preview"><h3>待发布配置（凭据已隐藏）</h3><pre>{{JSON.stringify(preview.configuration,null,2)}}</pre><button class="primary" :disabled="busy" @click="publish">确认发布新版本</button></div><h3>发布历史</h3><div v-for="v in versions" :key="v.revision" class="history"><span>v{{v.revision}} · {{time(v.createdAt)}}<small>{{v.note||'无备注'}}</small></span><button v-if="v.revision!==selected.revision" :disabled="busy" @click="rollback(v.revision)">回滚为新版本</button></div><p v-if="!versions.length" class="muted">尚无发布历史。</p><h3>最近应用反馈</h3><div v-for="report in feedback" :key="report.deviceId" class="history"><span>{{report.platform}} · App {{report.versionCode}} · 配置 v{{report.revision}}<small>{{report.status}} {{report.errorCode}} · {{time(report.seenAt)}}</small></span></div><p v-if="!feedback.length" class="muted">尚无反馈，最近报告不代表设备当前在线。</p></section>
    </div>
    <div v-else><div class="section-heading"><h2>配置模板</h2><button class="primary" :disabled="busy" @click="editEntity()">新建{{labels[tab]}}</button></div><p class="muted">密码以加密形式保存，不在列表返回。更新草稿后请预览受影响订阅并发布。</p><div class="cards"><article v-for="entity in entities[tab]" :key="entity.id"><h3>{{entity.label}}</h3><dl v-for="(value,key) in entity.data" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></dl><p v-if="entity.hasPassword" class="muted">密码：********</p><p class="muted">关联 {{related(entity)}} 条订阅</p><div class="actions"><button :disabled="busy" @click="editEntity(entity)">编辑</button><button class="danger" :disabled="busy||related(entity)>0" @click="deleteEntity(entity)">删除</button></div></article><p v-if="!entities[tab].length" class="empty">暂无配置。</p></div></div>
   </main>
  </div>
  <div v-if="entityDraft&&tab!=='subscriptions'" class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="entity-title"><h2 id="entity-title">{{entityDraft.id?'编辑':'新建'}}{{labels[tab]}}</h2><form @submit.prevent="saveEntity"><label>名称<input v-model="entityDraft.label" required maxlength="120"></label><template v-if="tab==='proxy'"><label>代理地址<input v-model="entityDraft.data.host" required placeholder="proxy.example.com" maxlength="253"></label><label>端口<input v-model.number="entityDraft.data.port" type="number" min="1" max="65535" required></label><label>代理账号<input v-model="entityDraft.data.username" maxlength="256"></label><label>代理密码<input v-model="entityDraft.data.password" type="password" autocomplete="new-password" :placeholder="entityDraft.hasPassword?'留空保持已保存密码':'可留空'" maxlength="1024"></label></template><label v-if="tab==='server'">服务器地址<input v-model="entityDraft.data.baseUrl" type="url" required placeholder="http://jellyfin.internal:8096/jellyfin" maxlength="2048"></label><template v-if="tab==='credential'"><label>所属服务<select v-model="entityDraft.data.serverId" required><option v-for="server in entities.server" :key="server.id" :value="server.id">{{server.label}}</option></select></label><label>Jellyfin 账号<input v-model="entityDraft.data.username" required maxlength="256"></label><label>Jellyfin 密码<input v-model="entityDraft.data.password" type="password" autocomplete="new-password" :required="!entityDraft.hasPassword" :placeholder="entityDraft.hasPassword?'留空保持已保存密码':''" maxlength="1024"></label></template><template v-if="tab==='policy'"><label>分辨率上限<select v-model="entityDraft.data.resolution"><option v-for="value in resolutions" :key="value" :value="value">{{resolutionNames[value]}}</option></select></label><label>合计码率上限<select v-model="entityDraft.data.totalBitrateBps"><option v-for="value in rates" :key="value" :value="value">{{rateLabel(value)}}</option></select></label></template><p v-if="error" class="error" role="alert">{{error}}</p><div class="actions"><button type="button" :disabled="busy" @click="entityDraft=null">取消</button><button class="primary" :disabled="busy">保存草稿</button></div></form></section></div>
  <div v-if="subscriptionDraft" class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="subscription-title"><h2 id="subscription-title">{{subscriptionDraft.id?'编辑':'新建'}}订阅</h2><form @submit.prevent="saveSubscription"><label>使用者名称<input v-model="subscriptionDraft.label" required maxlength="120"></label><label v-if="!subscriptionDraft.id">指定令牌（可选）<input v-model="subscriptionToken" type="password" autocomplete="off" maxlength="43" placeholder="留空随机生成；灾后恢复请填写原令牌"><small>原令牌唯一绑定此订阅。恢复原令牌并发布后，设备无需重新填写链接。</small></label><label>HTTP 代理<select v-model="subscriptionDraft.proxyId"><option value="">不使用代理（直连）</option><option v-for="e in entities.proxy" :key="e.id" :value="e.id">{{e.label}}</option></select><small>直连需要 App 0.6.58 或更新版本；服务地址须能从手机直接访问。</small></label><label>个人授权<select v-model="subscriptionDraft.credentialId" required><option v-for="e in entities.credential" :key="e.id" :value="e.id">{{e.label}}</option></select></label><label>播放策略<select v-model="subscriptionDraft.policyId" required><option v-for="e in entities.policy" :key="e.id" :value="e.id">{{e.label}}</option></select></label><label>检查间隔（秒）<input v-model.number="subscriptionDraft.refreshIntervalSeconds" type="number" min="300" max="86400" required></label><label>最低客户端构建号<input v-model.number="subscriptionDraft.minClientVersionCode" type="number" min="57" required></label><p v-if="error" class="error" role="alert">{{error}}</p><div class="actions"><button type="button" :disabled="busy" @click="subscriptionDraft=null;subscriptionToken=''">取消</button><button class="primary" :disabled="busy">保存草稿</button></div></form></section></div>
<div v-if="restoreLinkDialog" class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="restore-link-title"><h2 id="restore-link-title">补录原订阅链接</h2><p>旧版本仅保存令牌摘要。请从手机设置复制原链接，或填写备份的原令牌；补录不会更换令牌或影响现有设备。</p><form @submit.prevent="restoreOriginalLink"><label>原订阅链接或令牌<input v-model="originalLink" type="password" autocomplete="off" maxlength="2048" required placeholder="原订阅链接，或 43 位令牌"></label><p v-if="error" role="alert" class="error">{{error}}</p><div class="actions"><button type="button" :disabled="busy" @click="restoreLinkDialog=false;originalLink=''">取消</button><button class="primary" :disabled="busy">验证并保存、复制</button></div></form></section></div>
  <div v-if="tokenDialog" class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="token-title"><h2 id="token-title">设置／恢复令牌</h2><p>输入已备份的原令牌可恢复原链接；不同订阅不能使用同一令牌。此操作可更换或恢复令牌。如只需复制现有链接，请使用详情页的复制按钮。</p><form @submit.prevent="updateToken(false)"><label>指定令牌<input v-model="tokenValue" type="password" autocomplete="off" maxlength="43" placeholder="43 位 Base64URL 令牌"></label><p v-if="error" role="alert" class="error">{{error}}</p><div class="actions"><button type="button" :disabled="busy" @click="tokenDialog=false;tokenValue=''">取消</button><button type="button" :disabled="busy" @click="updateToken(true)">随机轮换</button><button class="primary" :disabled="busy">保存指定令牌</button></div></form></section></div>
  <div v-if="link" class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="link-title"><h2 id="link-title">保存订阅链接</h2><p>服务器已加密保存令牌，可在订阅详情再次复制链接。请像密码一样保管；首次创建后还需发布配置。</p><p v-if="link.startsWith('http:')" class="muted">当前链接为 HTTP。Android 订阅要求 HTTPS，请从手机可达的 HTTPS 地址打开后台后生成链接。</p><textarea :value="link" readonly rows="5" aria-label="订阅链接"></textarea><div class="actions"><button @click="copyLink">复制链接</button><button class="primary" @click="link=''">已保存，关闭</button></div></section></div>
  <div v-if="passwordDialog" class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="password-title"><h2 id="password-title">修改管理员密码</h2><form @submit.prevent="changePassword"><label>当前密码<input v-model="password.oldPassword" type="password" required autocomplete="current-password"></label><label>新密码<input v-model="password.newPassword" type="password" minlength="8" maxlength="1024" required autocomplete="new-password"></label><p v-if="error" role="alert" class="error">{{error}}</p><div class="actions"><button type="button" @click="passwordDialog=false;password.oldPassword='';password.newPassword=''">取消</button><button class="primary" :disabled="busy">更新并重新登录</button></div></form></section></div>
 </div>
</template>
